INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter25-gandhijis-tours-in-telangana', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter25-gandhijis-tours-in-telangana-p1", "partName": "Gandhi''s 1928 Letter to Hyderabad", "bodyMd": "Before his personal visits, Gandhi''s connection with the Nizam''s dominions began through correspondence on the khadi movement.\n\n*   On **7 June 1928**, Gandhi wrote a letter from the Satyagraha Ashram to **Maharaja Kishan Prasad** (a nobleman of Hyderabad state).\n*   In the letter, Gandhi acknowledged that Kishan Prasad and his household were personally practising and promoting khadi, and that he had learned this through **Roopalal**.\n*   Gandhi noted that the **Mysore princely state** was at the forefront of the khadi movement among Indian states and held it up as an example.\n*   He appealed to Kishan Prasad to lead the khadi movement in the Nizam''s dominions as a mission, framing it as service to the poor of that state.\n*   He requested Kishan Prasad to send him a sample of khadi cloth woven by his eldest son, to be displayed at exhibitions.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter25-gandhijis-tours-in-telangana-p2", "partName": "Gandhi''s First Visit to Hyderabad (April 1929)", "bodyMd": "### Arrival and Reception\n\n*   Gandhi''s **first Hyderabad tour began in April 1929**.\n*   **Krishnaswami Mudiraj** took his Andhra volunteer corps to the station to receive Gandhi and brought him to the venue amid a warm welcome.\n*   The platform was decorated, and as the crowd swelled with people climbing onto the platform, the situation grew increasingly congested.\n*   Recognising the difficulty of moving Gandhi through the dense crowd, Mudiraj, using presence of mind, arranged for a train stop at a different point and, with the protection of his own volunteers, safely brought Gandhi out from the rear, away from the crowd.\n*   Gandhi was seated in a car that had been readied in advance and was taken in a procession through the city.\n*   **Andhra band troupes** performed music during the procession.\n\n### Public Meeting at Vivekavardhini Grounds\n\n*   Gandhi reached the Vivekavardhini grounds accompanied by local leaders **Vaman Naik**, **Madapati Hanumantha Rao**, **Mandumula Narasimha Rao**, **R.S. Naik**, **Raja Bansilal**, and **Mukunddas Malani**.\n*   A grand public meeting was held there under the chairmanship of **Vaman Naik**.\n*   **Speech themes:**\n    *   Gandhi described **khadi and the Kamadhenu (wish-fulfilling cow)** as things that fully provide for the nation.\n    *   He said Hyderabad had good scope for wider adoption of khadi, and that with further progress, help and cooperation could also be extended to people elsewhere in India.\n    *   He mentioned that **Sarojini Naidu** had told him about the good prospects for khadi weavers in the region.\n    *   He noted that untouchability persisted extensively within the Hyderabad state; he called it unwarranted and an urgent problem needing to be addressed, adding that this practice had no basis in scripture and urged Hindus to free themselves from it.\n\n### Donations and Other Engagements\n\n*   Following the speech, **Raja Dhanraj Girji** offered **Rs. 2,000** and **Mukund Rao** offered **Rs. 100** to Gandhi.\n*   Gandhi responded to a memento presented by **Vaman Naik** on behalf of patriotic citizens, thanking them for the contribution made for \"Daridranarayana\" (the poor as manifestations of God), and spoke about the condition of poverty in India, noting that many families survive on one meal in three days and describing cattle as their \"Kamadhenu.\"\n*   He mentioned that he himself had toured extensively — travelling 5–6 miles daily even in villages — in order to reach out to the poorest.\n*   He appealed to the wealthy to help the poor reach the standard of British India, adding that if unity and dedicated effort continued for just one more year, all of India would achieve the necessary prosperity.\n*   He acknowledged people''s fondness for fine and foreign cloth but appealed that, keeping fellow Indians in mind, they should wear coarse cloth and thereby help them; this, he said, would also let liquor consumption naturally decline, since British India''s education was funded partly from liquor revenue, which he called shameful.\n*   He condemned viewing \"Adi Hindus\" (Harijans) as untouchable, calling it a stain on Hinduism with no scriptural or religious basis, and appealed to Hindu brethren to give up this sin; he mentioned feeling satisfied on being told that the garland placed around his neck had been made by Harijans, adding he would never look down on such a garland.\n*   The speech collected donations of **Rs. 12,000**.\n*   Gandhi visited the **Balika Hindi Pathashala** (girls'' Hindi school) established by Krishnaswami Mudiraj at Chudi Bazaar and expressed satisfaction.\n*   On **7 April 1929**, a women''s meeting in Gandhi''s honour was organised at the **Prem Theatre**, Sultan Bazaar.\n\n### Departure\n\n*   Gandhi departed Hyderabad by train for Vijayawada at **9:15 pm**.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter25-gandhijis-tours-in-telangana-p3", "partName": "Gandhi''s Second Visit to Hyderabad (March 1934)", "bodyMd": "### Arrival\n\n*   Gandhi''s second tour began on **9 March 1934**, about six years after the first.\n*   **Sarojini Naidu** arrived in Hyderabad three days in advance to oversee arrangements for the visit.\n*   Two days before, on the 7th, Harijan Sevadal chief secretary **Rao Narayana Reddy**, **L.R. Dacha**, **Basanta Rao**, and **Kumari Padmajanayudu** went to receive Gandhi at the station, but were able to meet him only at **Vikarabad station**.\n*   To shield Gandhi from the crush of the crowd, he was brought down instead at **Lingampalli**, 15 miles from the city.\n*   Since word of this had reached in advance, **Sarojini Naidu**, **Kumari Leelamani Naidu**, Major **Muthyala Govindarajulu Naidu**, **Vamana Naik**, **Sirajul Hasan Tirmizi**, **Vinayaka Rao Vidyalankar**, **K. Tatachari**, and **Ramakrishna Dhat**, among others, went to receive him there.\n*   Sarojini Naidu gave the first welcome, garlanding Gandhi with khaddar flowers, and took him to her residence, **\"Golden Threshold\"** in Abids.\n*   Family members, including **Mira Behn**, accompanied Gandhi.\n\n### Donations at Lingampalli and the Public Programme\n\n*   At Lingampalli station, a Muslim woman named **Musalamma** rushed to Gandhi''s car carrying two bangles as a gift; Gandhi accepted the gift with a smile.\n*   Another woman addressed Gandhi as **\"Lokarakshaka\"** (protector of the world) and offered a rupee, which Gandhi gratefully accepted, thanking her.\n*   Police Commissioner **Kotwal Venkatarama Reddy** arranged tight security at Golden Threshold, where Gandhi was staying.\n*   Gandhi later drove out along Lal Darwaza, where crowds on both sides greeted him; streets were decorated with festoons.\n*   He visited the **Adi Hindu Vidyalayam**.\n*   Further visits planned for that programme — to **Shanti Bhavan**, the **Marwadi Vidyalayam**, and the **Kachiguda Harijan hostel** — had to be cancelled because Gandhi was unwell/fatigued, disappointing the crowds who had gathered enthusiastically; the government subsequently did not permit the remaining scheduled programmes.\n*   **Mejaru Muthyala Govindarajula Naidu** led a large deputation to greet Gandhi; local Harijan Sevaka Sangham president **Vaman Naik** presented a welcome address.\n\n**Donations collected on this occasion:**\n\n| Donor | Amount (Rs.) | Purpose |\n|---|---|---|\n| Harijan Seva Sangham | 1,630 | Harijan fund |\n| Lal Darwaza citizens | 75 | Harijan fund |\n| Marwadi Vidyalayam | 100 | Harijan fund |\n| Arya Samaj | 150 | Harijan fund |\n\n### Speech on Humanity and Equality\n\n*   Gandhi''s address at this stage covered several points:\n    *   All human beings are one; there should be no distinctions of gradation among them.\n    *   There should be no difference between Harijans and others.\n    *   There should be no divisions between Hindus and Muslims.\n    *   God may be called \"Allah\" or \"Ishwara\" — whatever name is used, all serve the same God.\n    *   Hindus must eradicate the stain of untouchability, and he appealed to fellow Hindus to help remove it.\n    *   He expressed happiness on learning that the garland of \"chaste thread\" placed around his neck had been made by Harijans, and said he had never looked down on such thread.\n    *   He appealed to everyone to come forward for the Harijan upliftment programme.\n*   His speech that day raised **Rs. 12,000**.\n*   Gandhi also visited and expressed satisfaction with the **Balika Hindi Pathashala** established by Krishnaswami Mudiraj at Chudi Bazaar during this tour.\n\n### Secunderabad Meeting (9 March 1934)\n\n*   On the evening of **9 March 1934**, at **5 pm**, a large public meeting was held at the **Karbala grounds, Secunderabad**.\n*   Citizens'' representative **Bajeekrishna Rao** delivered the welcome address and donated money to the Harijan fund.\n*   Girl students of the **Begumpet Kanyagurukula Balika Pathasala** sang \"Vande Mataram\" and then recited a **\"panasa\" verse from the Vedas**.\n*   Gandhi, surprised at this, remarked that children reciting the Vedas was, in itself, the removal of untouchability as far as he was concerned.\n*   Gandhi told the gathering: he had come to Hyderabad for the eradication of untouchability, and asked for the people''s cooperation in this work, which he said he was undertaking for his own spiritual satisfaction (atmasuddhi).\n*   He said his mission had no ill will towards any particular religious community, and mentioned **Dr. Latif Sayeed**, a doctor of an upper-class religious background, who was devoted to treating Harijan patients — Gandhi called service to Harijans \"the divine duty of Hindus.\"\n*   **R.S. Naik**, known for successfully conducting auctions, was invited to auction articles at the meeting.\n*   Gandhi took about 15 minutes to reach the platform from where the car was parked because of the crowd.\n*   At **Secunderabad station**, in a short span, **Rs. 225** was collected.\n*   At **Kazipet station**, **Ravi Narayana Reddy** presented Gandhi with **Rs. 1,900**.\n*   **Total collections from Hyderabad and Secunderabad cities during this tour reached about Rs. 10,000.**\n\n### The Mango Tree Memorial\n\n*   When Gandhi had earlier undergone imprisonment at the **Yerawada jail**, he had once rested beneath a mango tree there.\n*   A sapling grew from a seed of that tree, and he carried this sapling with him.\n*   As a memento of that occasion, this sapling was planted at **Golden Threshold**.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter25-gandhijis-tours-in-telangana-p4", "partName": "Gandhi''s Third Visit — Khammam, Dornakal, Manukota and Warangal (1946)", "bodyMd": "### Background: The Andhra Mahasabha''s Invitation\n\n*   In late **January 1946**, Gandhi went to Madras to attend the celebrations of the **Dakshina Bharat Hindi Prachar Sabha**.\n*   On his return journey via the **Khazipet route**, the **Andhra Mahasabha** decided that if Gandhi visited the key centres of Telangana — **Khammam** and **Warangal** — it would give the freedom struggle in Telangana fresh impetus.\n*   Gandhi initially declined this request.\n*   Mahasabha leaders then sent **M.S. Rajalingam**, who was already acquainted with Gandhi, to Madras to press the request in person.\n*   Rajalingam met Gandhi in Madras and also consulted with **Gollapudi Seetaramasastri**.\n*   Rajalingam explained to Gandhi that Telangana was, on one side, facing Muslim League propaganda, and on the other side, activity by Communists, creating adverse conditions in the region, and that a visit by Gandhi would give the people moral strength.\n*   Hearing this, Gandhi agreed and assured that he would visit wherever necessary in the region.\n*   A **special train** was arranged for Gandhi''s tour.\n\n### Mobilisation Before the Visit\n\n*   As soon as Gandhi''s acceptance was known, Rajalingam informed the Mahasabha leaders of the news.\n*   Since only two to three days remained, workers at **Madhira**, **Manukota**, and **Dornakal** were informed at once.\n*   Leaflets were sent out to villages without delay.\n*   **Swami Ramananda Tirtha** was not in town at the time; a worker was specially sent to bring **Mandumula Narasimha Rao**.\n*   Rajalingam accompanied Gandhi on the train.\n\n### Khammam\n\n*   In Khammam, Andhra Mahasabha town committee president **Gellu Keshava Rao** and Khammam Merchants'' Association president **Suggula Akshaya Linga Gupta** collected a fund of thousands of rupees.\n*   The special train was stopped in a large open ground near the **Venkatagiri level crossing gate** in Khammam.\n*   Crowds thronged in wave after wave to see Gandhi.\n*   **Sardar Jamalapuram Keshava Rao** managed and controlled the crowds.\n*   A platform **15 feet high** was built about a quarter-mile from the railway station.\n*   The gathering of people began from **8 pm the previous night**.\n*   Volunteers collected **Rs. 1,500** overnight from the crowd waiting there.\n*   The special train arrived at **8:30 am**.\n*   Gandhi, along with **Krishna Das**, **Unnava Rajagopala Krishnayya**, and **M.S. Rajalingam**, who had come along, sat on the platform.\n*   A welcome address was presented to Gandhi along with **1,000 gold sovereign coins** wrapped in a silk cloth.\n*   Gandhi humorously remarked, **\"So this silk cloth also isn''t mine?\"**, drawing laughter, and addressed the silent crowd.\n*   **Gandhi''s appeal to the gathering:**\n    *   All the people should stay united, setting aside caste and religious differences.\n    *   Everyone should wear khadi cloth.\n    *   Everyone should give up liquor.\n    *   The people should earn the worthiness needed for the self-rule that would soon come.\n\n### Dornakal\n\n*   Despite being a small town, about **700 people** of Dornakal came to see Gandhi and offered a donation of **Rs. 4,000**.\n*   At **Gundrati Madugu**, **400 Harijans** devotedly met Gandhi and offered **Rs. 2,000** to the fund.\n*   At the Dornakal station halt, Gandhi wished to bathe; the stationmaster initially refused permission, fearing for his job, but eventually agreed and, with help from those present, arranged buckets of water so that Gandhi could bathe in the station bathroom.\n\n### Manukota\n\n*   About **800 people** gathered at Manukota, and they contributed **Rs. 700** to the Harijan fund.\n\n### Warangal\n\n*   Propaganda that Gandhi would come to Warangal began circulating from **5 February 1946**.\n*   Two to three days beforehand, leaders had campaigned vigorously in the surrounding villages.\n*   Volunteers of the Warangal and Hanamkonda student associations, about **800** in number, gathered at Warangal station shouting slogans of **\"Swatantra Bharatiki Jai.\"' WHERE chapter_slug = 'telangana-history-en-chapter25-gandhijis-tours-in-telangana';
UPDATE theory_content SET concepts_json = concepts_json || '**\n*   Near **Goodur station**, a decision was made on the exact spot for Gandhi''s darshan and message.\n*   Though the scheduled time was **9:20 am**, people began gathering from as early as **5 am**.\n*   The special train fell behind schedule; it was reaching stations along the way **12–20 hours late** at intermediate points.\n*   People who came to see Gandhi at these stops collected donations amounting to tens of thousands of rupees; some women contributed gold ornaments generously.\n*   The reception committee formed to make Gandhi''s tour a success included **Hayagrivachari**, **M.S. Rajalingam**, **Bhandaru Chandramouleshwara Rao**, **S. Sreeramulu Naidu**, **S. Chandramouli**, and **B. Ranganayakulu**.\n*   Committee president **T. Hayagrivachari** donated **Rs. 15,000** to the Harijan fund.\n*   **Chandra Kanthaiah** alone gave **Rs. 5,000**.\n*   A Harijan girl applied a tilak to Gandhi''s forehead with a smile, which he accepted graciously.\n*   At **12:30 pm**, the special train halted on the Warangal platform; Gandhi came down, stood briefly, and looked at the vast, devoted crowd that had waited since morning enduring sun and hunger — a scene described as truly moving, with tears of joy in the eyes of onlookers.\n*   It was said that Warangal''s soil became sanctified by Gandhi''s footsteps, and that his ten minutes there were equal to ten years.\n*   **Hayagrivachari**, **Rajalingam**, and some other leaders accompanied Gandhi on the special train up to **Khazipet**.\n*   As a result of the leaders'' efforts, Gandhi''s tour brought about a great awakening (chaitanyam) among the people of Telangana.\n\n### Farewell Message from Kazipet\n\n*   Before the special train crossed the borders of Telangana, Gandhi issued a message to the people of Andhra, from **Kazipet**, dated **5 February 1946**.\n*   **Key points of the message:**\n    *   He had great hope for the Andhra region and trusted it would fully realise his aims.\n    *   Untouchability should be completely removed.\n    *   All temples should be opened for Harijans.\n    *   Everyone should wear khadi clothing.\n    *   Liquor should be given up.\n    *   National unity should be protected.\n    *   Along with the mother tongue, the national language, **Hindustani**, should be learned in both the **Devanagari** and **Urdu** scripts.\n*   The message was signed: **M.K. Gandhi, Kazipet, 5-2-1946.**", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter25-gandhijis-tours-in-telangana';
